#!/bin/bash# 单测 run.sh 里的 mark_ok / mark_fail 两个函数，不连网、不碰真档案。# 2026-10-26 16:00 写：搬机器把这两个函数弄丢过一次，以后每次改 run.sh 都跑一遍。set -uo pipefailSRC="${1:-$HOME/../life-sync/run.sh}"TMP=$(mktemp -d)trap 'rm -rf "$TMP"' EXITHERE="$TMP"LOG="$TMP/sync.log"ARCH="$TMP/arch"mkdir -p "$ARCH"printf '# 没做完的事\n\n- [ ] 原有的一条\n' > "$ARCH/open_loops.md"fail=0chk() { if [ "$2" = "$3" ]; then echo "  ok   $1（$2）"; else echo "  FAIL $1（得到 $2，期望 $3）"; fail=1; fi }# 把要测的函数从 run.sh 里抠出来（不执行整个脚本）。# say 和 mark_ok 都是单行函数，mark_fail 是块；一起抠，别漏 ——# 第一次写漏了 say，测试照样"全过"，但 stderr 里五次 say 报错，等于测了个假的。eval "$(grep -E '^say\(\)' "$SRC")"eval "$(grep -E '^mark_ok\(\)' "$SRC")"eval "$(sed -n '/^mark_fail()/,/^}/p' "$SRC")"for fn in say mark_ok mark_fail; do  if ! declare -F "$fn" >/dev/null; then echo "抠不出 $fn，测试本身是坏的" >&2; exit 9; fidoneecho "mark_fail 连败计数与告警："mark_fail >/dev/nullchk "第1次" "$(cat "$HERE/fail-streak")" "1"mark_fail >/dev/nullchk "第2次" "$(cat "$HERE/fail-streak")" "2"chk "2次时还不该写 loops" "$(grep -c '备份连败' "$ARCH/open_loops.md")" "0"mark_fail >/dev/nullchk "第3次" "$(cat "$HERE/fail-streak")" "3"chk "3次写了 loops" "$(grep -c '备份连败' "$ARCH/open_loops.md")" "1"mark_fail >/dev/nullchk "第4次 streak 继续涨" "$(cat "$HERE/fail-streak")" "4"chk "但不重复写 loops" "$(grep -c '备份连败' "$ARCH/open_loops.md")" "1"echo "mark_ok 清计数："mark_okchk "fail-streak 没了" "$([ -f "$HERE/fail-streak" ] && echo 在 || echo 没了)" "没了"echoif [ "$fail" = "0" ]; then echo "全过"; exit 0; else echo "有失败"; exit 1; fi